new file mode 100644
index 0000000..a9c9311
--- /dev/null
+++ b/repro/report.js
@@ -0,0 +1,9 @@
+/* eslint no-useless-assignment: "error" */
+
+// shows error
+[1, 2, 3].map(i => ++i);
+[1, 2, 3].map(i => --i);
+
+// no error
+[1, 2, 3].map(i => i + 1);
+[1, 2, 3].map(i => i - 1);
diff --git a/repro/repro-19818.js b/repro/repro-19818.js
new file mode 100644
index 0000000..01d355d
--- /dev/null
+++ b/repro/repro-19818.js
@@ -0,0 +1,31 @@
+"use strict";
+// Reproduction for no-useless-assignment false positive with prefix ++/-- (ESLint 9.28.0).
+const { Linter } = require("../lib/api");
+const linter = new Linter();
+const config = { rules: { "no-useless-assignment": "error" } };
+
+const cases = [
+	// [code, expectedErrorCount]  -- the value of a prefix update / assignment expression IS used
+	["[1, 2, 3].map(i => ++i);", 0],
+	["[1, 2, 3].map(i => --i);", 0],
+	["[1, 2, 3].map(i => i + 1);", 0],
+	["[1, 2, 3].map(i => i - 1);", 0],
+	["function f(i) { return ++i; }", 0],
+	["function f(i) { return i += 1; }", 0],
+	["[1, 2, 3].map(i => (i = i + 1));", 0],
+	["function f() { let x = 0; return ++x; }", 0],
+	["function f() { let x = 0; console.log(++x); }", 0],
+	// postfix: the new value really is never read -> report is arguably correct
+	["[1, 2, 3].map(i => i++);", 1],
+];
+
+let failed = 0;
+for (const [code, expected] of cases) {
+	const msgs = linter.verify(code, config);
+	const ok = msgs.length === expected;
+	if (!ok) failed++;
+	console.log(`${ok ? "ok  " : "FAIL"} expected ${expected}, got ${msgs.length}: ${code}`);
+	for (const m of msgs) console.log(`       ${m.line}:${m.column} ${m.ruleId} ${m.message}`);
+}
+console.log(`\n${failed} case(s) behaving unexpectedly`);
+process.exitCode = failed ? 1 : 0;
